#!/usr/bin/env bash
# Generated by Phase: IMPLEMENT | Feature: EVOL-048
# ============================================================================
# check-plan-approval.sh — PreToolUse hook (Edit|Write): one planning stage, never zero.
# A write to a governed path on a branch class with no framework planning phase needs an approved plan.
# ONE definition: python3 scripts/gate.py plan --path <file> (config/quality.json → planning). exit 1 = blocked.
# Exit 2 + message on stderr = the Claude Code blocking contract; a missing or broken reader blocks too
# (fail-closed: governance not delivered). Documentation targets pass without a plan; gate inputs never do.
# ============================================================================
FILE=$(python3 -c '
import json, sys
try:
    d = json.load(sys.stdin); print((d.get("tool_input") or {}).get("file_path") or "")
except Exception:
    pass
' 2>/dev/null)
[ -n "$FILE" ] || exit 0
if ! command -v python3 >/dev/null 2>&1 || [ ! -f scripts/gate.py ]; then
  echo "BLOCKED: the governance reader (scripts/gate.py) is not available — the write to '$FILE' cannot be judged against the planning gate. Resolution: bash scripts/factory-sync.sh, then retry." >&2
  exit 2
fi
OUT=$(python3 scripts/gate.py plan --path "$FILE" 2>&1); RC=$?
case "$RC" in
  0) exit 0 ;;
  1) { echo "BLOCKED: no approved plan covers this write to '$FILE'."; echo "$OUT"; } >&2; exit 2 ;;
  *) { echo "BLOCKED: the planning gate could not judge the write to '$FILE' (gate.py plan exit $RC): $OUT"; echo "Resolution: fix config/quality.json → planning or scripts/gates from the shell, then retry."; } >&2; exit 2 ;;
esac
